WITH valid AS (SELECT *, CONCAT_WS(',', method, status) AS method_status_key, CEIL(amount) AS amount_whole, COALESCE(method, 'UNKNOWN') AS method_filled FROM payments WHERE status = 'SUCCESS' AND method IS NOT NULL), filtered AS (SELECT *, FLOOR(amount_whole) AS amount_whole_whole FROM valid WHERE method IS NOT NULL AND method <> 'cash'), enriched AS (SELECT *, FIRST_VALUE(amount_whole_whole) IGNORE NULLS OVER (PARTITION BY order_id, method ORDER BY amount_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_amount_whole_whole, FIRST_VALUE(amount, TRUE) OVER (PARTITION BY method ORDER BY amount_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_amount, COUNT(amount_whole) OVER (PARTITION BY TO_DATE(paid_at)) AS paid_at_to_date_count_amount_whole FROM filtered), with_windows AS (SELECT id, order_id, method, amount, status, amount_whole, method_filled, amount_whole_whole, first_known_amount_whole_whole, first_known_amount, paid_at_to_date_count_amount_whole, SUM(first_known_amount) OVER w_part AS cumulative_first_known_amount, NTILE(10) OVER (PARTITION BY TO_DATE(paid_at), method ORDER BY paid_at_to_date_count_amount_whole DESC, id) AS paid_at_to_date_count_amount_whole_bucket, NTILE(10) OVER (PARTITION BY order_id, status ORDER BY amount, id) AS amount_bucket, ROUND(first_known_amount / SUM(first_known_amount) OVER (PARTITION BY method), 4) AS first_known_amount_share FROM enriched WINDOW w_part AS (PARTITION BY YEAR(paid_at), method ORDER BY paid_at_to_date_count_amount_whole, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT CASE WHEN first_known_amount_whole_whole >= 86 THEN 'LARGE' ELSE 'SMALL' END AS first_known_amount_whole_whole_tier, order_id, MAX(first_known_amount) AS max_first_known_amount, APPROX_PERCENTILE(first_known_amount_share, 0.95) AS first_known_amount_share_p95, SUM(amount) FILTER (WHERE method = 'card') AS card_total_amount, SUM(CASE WHEN method = 'card' THEN amount_whole ELSE 0 END) AS card_amount_whole, GROUPING(CASE WHEN first_known_amount_whole_whole >= 86 THEN 'LARGE' ELSE 'SMALL' END) AS grouping_id FROM with_windows GROUP BY GROUPING SETS ((CASE WHEN first_known_amount_whole_whole >= 86 THEN 'LARGE' ELSE 'SMALL' END, order_id), (CASE WHEN first_known_amount_whole_whole >= 86 THEN 'LARGE' ELSE 'SMALL' END)) HAVING APPROX_PERCENTILE(first_known_amount_share, 0.95) > 0
